# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İYON OLUŞUMU: KATYON, ANYON VE İZOELEKTRONİK TANECİKLER</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">OKTET - DUBLET VE İYON OLUŞUMU</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Dublet Kuralı: Son katmanı 2 elektrona (₂He)</text>\n  <text x="52" y="113" font-size="10.5" fill="#334155">tamamlama ( Örn: ₃Li → Li⁺ [2] )</text>\n  <text x="42" y="138" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Oktet Kuralı: Son katmanı 8 elektrona (₁₀Ne, ₁₈Ar)</text>\n  <text x="52" y="155" font-size="10.5" fill="#334155">tamamlama eğilimi</text>\n  <text x="42" y="180" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Katyon (+): Elektron veren tanecik (Yarıçap küçülür)</text>\n  <text x="42" y="202" font-size="11.5" font-weight="bold" fill="#dc2626">• Anyon (-): Elektron alan tanecik (Yarıçap büyür)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">₁₀Ne (2-8) İLE İZOELEKTRONİK TANECİKLER</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#14532d">• ₈O (2-6) + 2e⁻ → ₈O²⁻ (2-8)  [10 elektron, Anyon]</text>\n  <text x="377" y="120" font-size="11.5" font-weight="bold" fill="#14532d">• ₉F (2-7) + 1e⁻ → ₉F⁻ (2-8)   [10 elektron, Anyon]</text>\n  <text x="377" y="144" font-size="11.5" font-weight="bold" fill="#14532d">• ₁₁Na (2-8-1) - 1e⁻ → ₁₁Na⁺ (2-8) [10 e⁻, Katyon]</text>\n  <text x="377" y="168" font-size="11.5" font-weight="bold" fill="#14532d">• ₁₂Mg (2-8-2) - 2e⁻ → ₁₂Mg²⁺ (2-8) [10 e⁻, Katyon]</text>\n  <rect x="377" y="185" width="280" height="40" rx="6" fill="#dcfce7"/>\n  <text x="517" y="203" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">İzoelektroniklerde Yarıçap Sıralaması:</text>\n  <text x="517" y="219" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">₈O²⁻ &gt; ₉F⁻ &gt; ₁₀Ne &gt; ₁₁Na⁺ &gt; ₁₂Mg²⁺</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PERİYODİK ÖZELLİKLER: ATOM YARIÇAPI VE İYONLAŞMA ENERJİSİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">ATOM YARIÇAPI (HACMİ / ÇAPI)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#713f12">• Aynı Grupta Yukarıdan Aşağıya (↓): ARTAR</text>\n  <text x="52" y="114" font-size="10.5" fill="#334155">Katman (periyot) sayısı arttığı için çap büyür</text>\n  <text x="52" y="130" font-size="10.5" fill="#334155">(Kardan adamın gövdesi aşağı indikçe büyür).</text>\n  <text x="42" y="156" font-size="11.5" font-weight="bold" fill="#713f12">• Aynı Periyotta Soldan Sağa (→): AZALIR</text>\n  <text x="52" y="174" font-size="10.5" fill="#334155">Katman sayısı sabitken proton sayısı (çekirdek</text>\n  <text x="52" y="190" font-size="10.5" fill="#334155">çekim gücü) arttığı için elektronlar çekilir, çap küçülür.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">İYONLAŞMA ENERJİSİ (İE)</text>\n  <text x="377" y="94" font-size="11" fill="#334155">Gaz hâlindeki nötr atomdan 1 e⁻ koparmak için</text>\n  <text x="377" y="110" font-size="11" fill="#334155">verilen enerji: X(g) + İE₁ → X⁺(g) + e⁻</text>\n  <text x="377" y="135" font-size="11.5" font-weight="bold" fill="#581c87">• Aynı Grupta Yukarıdan Aşağıya (↓): AZALIR</text>\n  <text x="377" y="157" font-size="11.5" font-weight="bold" fill="#581c87">• Aynı Periyotta Soldan Sağa (→): GENELLİKLE ARTAR</text>\n  <rect x="377" y="172" width="280" height="54" rx="6" fill="#f3e8ff" stroke="#c084fc"/>\n  <text x="517" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Aynı Periyotta 1. İE Sıralaması (Küresel Simetri!):</text>\n  <text x="517" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">1A &lt; 3A &lt; 2A &lt; 4A &lt; 6A &lt; 5A &lt; 7A &lt; 8A</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ELEKTRONEGATİFLİK VE PERİYODİK ÖZELLİKLERİN ÖZET YÖNLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">ELEKTRONEGATİFLİK (BAĞ ELEKTRONUNU ÇEKME)</text>\n  <text x="42" y="96" font-size="11" fill="#334155">• Kimyasal bağdaki ortaklaşa kullanılan elektronları</text>\n  <text x="52" y="113" font-size="11" fill="#334155">çekme gücüdür (Soy gazlarda bağ olmadığı için yok!).</text>\n  <text x="42" y="138" font-size="11.5" font-weight="bold" fill="#7c2d12">• Soldan Sağa (→): ARTAR (En yüksek 7A grubu)</text>\n  <text x="42" y="160" font-size="11.5" font-weight="bold" fill="#7c2d12">• Yukarıdan Aşağıya (↓): AZALIR</text>\n  <rect x="42" y="178" width="280" height="46" rx="6" fill="#ffedd5"/>\n  <text x="182" y="198" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#c2410c">En elektronegatif element: Flor (₉F = 4,0)</text>\n  <text x="182" y="215" text-anchor="middle" font-size="10.5" fill="#9a3412">Elektron ilgisi en yüksek element ise Klor (₁₇Cl)\'dur.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ÖZET DEĞİŞİM YÖNLERİ TABLOSU</text>\n  <text x="377" y="98" font-size="11.5" font-weight="bold" fill="#1d4ed8">Soldan Sağa (→) Gidildikçe:</text>\n  <text x="387" y="116" font-size="11" fill="#334155">• Atom yarıçapı ve metalik özellik AZALIR.</text>\n  <text x="387" y="134" font-size="11" fill="#334155">• İyonlaşma enerjisi (genellikle), elektronegatiflik</text>\n  <text x="395" y="150" font-size="11" fill="#334155">ve ametalik özellik ARTAR.</text>\n  <text x="377" y="178" font-size="11.5" font-weight="bold" fill="#15803d">Yukarıdan Aşağıya (↓) İnildikçe:</text>\n  <text x="387" y="196" font-size="11" fill="#334155">• Atom yarıçapı ve metalik özellik ARTAR.</text>\n  <text x="387" y="214" font-size="11" fill="#334155">• İE, elektronegatiflik ve ametalik özellik AZALIR.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
